import torch
import torch.nn as nn
import torch.nn.functional as F
import math
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p50_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor relu_attention_forward(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    double scale);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("relu_attention_forward", &relu_attention_forward,
          "Fused ReLU attention forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled fused ReLU-attention kernel.
// Q, K, V: [B, H, T, Dh] contiguous float32
// Output:  [B, H, T, Dh]
//
// Each block handles one (batch*head, query_tile) pair.
// We tile over key/value blocks, compute scaled dot-products,
// apply causal mask (key_idx > query_idx -> score=0), ReLU (clamp neg to 0),
// then immediately accumulate score*V into register accumulators.
// The full T x T attention matrix is never written to global memory.

#define TILE_Q 32
#define TILE_KV 32

__global__ void relu_attention_kernel(
    const float* __restrict__ Q,   // [BH, T, Dh]
    const float* __restrict__ K,   // [BH, T, Dh]
    const float* __restrict__ V,   // [BH, T, Dh]
    float* __restrict__ Out,        // [BH, T, Dh]
    int T,
    int Dh,
    float scale
) {
    // blockIdx.x = batch_head index
    // blockIdx.y = query tile index
    // threadIdx.x = query row within tile (0..TILE_Q-1)

    const int bh  = blockIdx.x;
    const int q_tile = blockIdx.y;
    const int q_row  = q_tile * TILE_Q + threadIdx.x;  // global query index

    const int stride_t = Dh;   // stride along T dimension

    // Shared memory for K and V tiles
    __shared__ float sK[TILE_KV][64];  // max Dh=64
    __shared__ float sV[TILE_KV][64];

    // Register accumulator for output row
    float acc[64];  // Dh <= 64 for head_dim
    #pragma unroll
    for (int d = 0; d < Dh; d++) acc[d] = 0.0f;

    // Load query row for this thread into registers
    float q_reg[64];
    if (q_row < T) {
        const float* q_ptr = Q + bh * T * Dh + q_row * Dh;
        #pragma unroll
        for (int d = 0; d < Dh; d++) q_reg[d] = q_ptr[d];
    }

    // Loop over KV tiles
    int n_kv_tiles = (T + TILE_KV - 1) / TILE_KV;
    for (int kv_tile = 0; kv_tile < n_kv_tiles; kv_tile++) {
        int kv_base = kv_tile * TILE_KV;

        // Collaborative load of K tile into shared memory
        // Each thread loads one row
        if (threadIdx.x < TILE_KV) {
            int k_row = kv_base + threadIdx.x;
            if (k_row < T) {
                const float* k_ptr = K + bh * T * Dh + k_row * Dh;
                #pragma unroll
                for (int d = 0; d < Dh; d++) sK[threadIdx.x][d] = k_ptr[d];
            } else {
                #pragma unroll
                for (int d = 0; d < Dh; d++) sK[threadIdx.x][d] = 0.0f;
            }
        }
        __syncthreads();

        // Compute scores for valid threads
        float scores[TILE_KV];
        if (q_row < T) {
            #pragma unroll
            for (int j = 0; j < TILE_KV; j++) {
                int k_row = kv_base + j;
                // Causal mask: only attend to k_row <= q_row
                if (k_row >= T || k_row > q_row) {
                    scores[j] = 0.0f;
                } else {
                    float dot = 0.0f;
                    #pragma unroll
                    for (int d = 0; d < Dh; d++) {
                        dot += q_reg[d] * sK[j][d];
                    }
                    // Scale and ReLU
                    dot *= scale;
                    scores[j] = dot > 0.0f ? dot : 0.0f;
                }
            }
        }
        __syncthreads();

        // Collaborative load of V tile into shared memory
        if (threadIdx.x < TILE_KV) {
            int v_row = kv_base + threadIdx.x;
            if (v_row < T) {
                const float* v_ptr = V + bh * T * Dh + v_row * Dh;
                #pragma unroll
                for (int d = 0; d < Dh; d++) sV[threadIdx.x][d] = v_ptr[d];
            } else {
                #pragma unroll
                for (int d = 0; d < Dh; d++) sV[threadIdx.x][d] = 0.0f;
            }
        }
        __syncthreads();

        // Accumulate score * V
        if (q_row < T) {
            #pragma unroll
            for (int j = 0; j < TILE_KV; j++) {
                if (scores[j] != 0.0f) {
                    #pragma unroll
                    for (int d = 0; d < Dh; d++) {
                        acc[d] += scores[j] * sV[j][d];
                    }
                }
            }
        }
        __syncthreads();
    }

    // Write output
    if (q_row < T) {
        float* out_ptr = Out + bh * T * Dh + q_row * Dh;
        #pragma unroll
        for (int d = 0; d < Dh; d++) out_ptr[d] = acc[d];
    }
}

torch::Tensor relu_attention_forward(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    double scale
) {
    TORCH_CHECK(q.is_cuda(), "q must be CUDA tensor");
    TORCH_CHECK(q.is_contiguous(), "q must be contiguous");
    TORCH_CHECK(k.is_contiguous(), "k must be contiguous");
    TORCH_CHECK(v.is_contiguous(), "v must be contiguous");
    TORCH_CHECK(q.dtype() == torch::kFloat32, "q must be float32");

    // q: [B, H, T, Dh]
    int B  = q.size(0);
    int H  = q.size(1);
    int T  = q.size(2);
    int Dh = q.size(3);

    TORCH_CHECK(Dh <= 64, "head_dim must be <= 64 for this kernel");

    auto out = torch::zeros({B, H, T, Dh}, q.options());

    int BH = B * H;
    int q_tiles = (T + TILE_Q - 1) / TILE_Q;

    dim3 grid(BH, q_tiles);
    dim3 block(TILE_Q);

    relu_attention_kernel<<<grid, block>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        out.data_ptr<float>(),
        T, Dh, (float)scale
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A multi-head masked self-attention layer with a projection at the end that uses ReLU instead of Softmax.
        It is possible to use torch.nn.MultiheadAttention here but I am including an
        explicit implementation here to show that there is nothing too scary here.
        """
    def __init__(self, n_embd, n_head, max_seqlen):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                             .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        B, T, C = x.size()
        head_dim = C // self.n_head
        _use_cuda_kernel = (x.is_cuda and x.dtype == torch.float32 and head_dim <= 64)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        k = k.view(B, T, self.n_head, head_dim).transpose(1, 2).contiguous()
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        q = q.view(B, T, self.n_head, head_dim).transpose(1, 2).contiguous()
        if _use_cuda_kernel:
            v = v.view(B, T, self.n_head, head_dim).transpose(1, 2).contiguous()
            y = _stark_get_extension().relu_attention_forward(q, k, v, 1.0 / math.sqrt(head_dim))
            y = y.transpose(1, 2).contiguous().view(B, T, C)
            return self.c_proj(y)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_8>>>
        att = F.relu(att)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_9>>>
        y = att @ v
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_10>>>
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_11>>>
        return y
        # <<<END_IMPROVE>>>

